function extractId(rdi: any): string | undefined {
  const mdsFields = rdi?.datasetVersion?.metadataBlocks?.MDS_fairagro?.fields || [];
  const idField = mdsFields.find((f: any) => f.typeName === 'MDS_fairagro.identifier');
  return idField?.value;
}

function extractFairness(rdi: any): any | undefined {
  const mdsFields = rdi?.datasetVersion?.metadataBlocks?.MDS_fairagro?.fields || [];
  const fairagroDataField = mdsFields.find((f: any) => f.typeName === 'MDS_fairagro.fairagroData');
  return fairagroDataField?.value?.FAIRness?.value;
}

